public interface IFileWriter
{
    void Write(string content);
}

public interface IConsoleWriter
{
    void Write(string content);
}

public class Writer : IFileWriter, IConsoleWriter
{
    // Explicit implementation for IFileWriter
    void IFileWriter.Write(string content) => File.WriteAllText("file.txt", content);

    // Explicit implementation for IConsoleWriter
    void IConsoleWriter.Write(string content) => Console.WriteLine(content);

    // Public method
    public void WriteToBoth(string content)
    {
        ((IFileWriter)this).Write(content);
        ((IConsoleWriter)this).Write(content);
    }
}
